import{_ as t,o as e,a as i,b as n}from"./app.DKoEZOcr.js";const l="/ascendc.github.io/pr/5487/assets/chan_split.DtX6oIv_.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_features"},{"text":"矩阵乘输出的Channel拆分","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_channel_split"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_channel_split.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_channel_split.md","outlineHeaders":[{"level":2,"title":"功能介绍","slug":"功能介绍","link":"#功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景","link":"#使用场景"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1786954352000}'),_={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_output_channel_split.md"};function s(p,a,r,o,c,m){return e(),i("div",null,[...a[0]||(a[0]=[n('<div><article class="markdown-body"><h1>矩阵乘输出的Channel拆分<span id="ZH-CN_TOPIC_0000002532228167"></span></h1><h2 id="功能介绍">功能介绍<span id="zh-cn_topic_0000002264134832_section310824820358"></span><a class="header-anchor" href="#功能介绍">​</a></h2><p>矩阵乘输出的Channel拆分，又称ChannelSplit。指当Matmul计算结果C矩阵的格式为<a href="../basics.html#zh-cn_topic_0000001622194138_section1453415011">NZ</a>时，C矩阵采用分形存储，关于NZ格式的详细内容请参考<a href="../basics.html#zh-cn_topic_0000001622194138_section1453415011">数据格式</a>。当C矩阵的物理排布格式为NZ、数据类型为float时，默认情况下，每个分形内部包含16*16个元素，即分形的大小为16*16。ChannelSplit的功能为将此场景下C矩阵的每个16*16的分形切分为16*8的分形，使得C矩阵按照16*8的分形进行存储。</p><p>由于1个float类型数据的大小为4字节，16*8的分形在内轴满足32字节对齐，内轴上的数据量与一条NPU矢量计算指令处理的数据单元一致，这便于后续的其它计算。ChannelSplit功能默认不启用，用户需通过设置<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/MatmulConfig.html">MatmulConfig</a>中的isEnableChannelSplit参数为true来开启此功能。</p><p><strong>图1</strong> ChannelSplit功能示意图<span id="zh-cn_topic_0000002264134832_fig38211632121711"></span><br><img src="'+l+`" alt title="ChannelSplit功能示意图"></p><h2 id="使用场景">使用场景<span id="zh-cn_topic_0000002264134832_section118051016163613"></span><a class="header-anchor" href="#使用场景">​</a></h2><p>对于NZ格式、float类型的C矩阵，需要按16*8的分形存储时，使用该功能。</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002264134832_section14160134220363"></span><a class="header-anchor" href="#约束说明">​</a></h2><p>开启ChannelSplit功能需满足：</p><ul><li>C矩阵的数据排布格式为CubeFormat::NZ。</li><li>C矩阵的数据类型为float。</li><li>C矩阵的内存逻辑位置为Global Memory。</li><li>矩阵乘结果L0C Buffer（CO1）数据类型为float。</li></ul><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002264134832_section15486294368"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_channelsplit_output">matmul_channelsplit算子样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 指定获取和修改的MatmulConfig模板
constexpr static MatmulConfigMode configMode = MatmulConfigMode::CONFIG_NORM;
// 修改模板参数isEnableChannelSplit=true，开启该MatmulConfig模板的ChannelSplit功能
constexpr static MatmulFuncParams funcParamsChannelSplit{
    false, false, false, false, 0, IterateOrder::ORDER_M, ScheduleType::INNER_PRODUCT, true, false, false, false, true/*isEnableChannelSplit*/
};
constexpr static MatmulConfig MM_CFG = GetMMConfig&lt;configMode&gt;(funcParamsChannelSplit);
Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, MM_CFG&gt; mm;

// 常规Matmul计算，最后输出分形为16*8
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);
mm.SetTensorA(gm_a);
mm.SetTensorB(gm_b);
mm.SetBias(gm_bias);
mm.IterateAll(gm_c);
</code></pre></div></article></div>`,1)])])}const u=t(_,[["render",s]]);export{h as __pageData,u as default};
